  const covered=t.insns.filter(i=>fuzzer.global.has(i.addr)).length,pct=Math.round(covered/t.insns.length*100);
  $('#fz-stats').innerHTML=`<div><span>Executions</span><b>${fuzzer.execs.toLocaleString()}</b></div><div><span>Corpus</span><b>${fuzzer.corpus.length}</b></div><div><span>Coverage</span><b>${covered}/${t.insns.length} · ${pct}%</b></div><div><span>Last input</span><b>0x${(fuzzer.lastInput>>>0).toString(16).padStart(8,'0')}</b></div>`;
  const st=$('#fz-status');
